using Xunit;

public class U09_AlarmsTest
{
    [Fact]
    public void TC_001_ControllerReportsProximalTubeConnected()
    {
        // Arrange
        var controller = new AlarmController();

        // Act
        var isConnected = controller.IsProximalTubeConnected();

        // Assert
        Assert.True(isConnected);
    }

    [Fact]
    public void TC_002_GUIComputesProximalTubeDisconnectAlarm()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.ComputeProximalTubeDisconnectAlarm();

        // Assert
        Assert.True(gui.IsProximalTubeDisconnectAlarmActive());
    }

    [Fact]
    public void TC_003_ProximalTubeDisconnectAlarmHasMediumPriority()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.SetPriority(AlarmPriority.Medium);

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.Priority);
    }

    [Fact]
    public void TC_004_GUIDetectsObstructionWhenVTILessThan100ml()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.DetectObstruction(90);

        // Assert
        Assert.True(gui.IsObstructionDetected());
    }

    [Fact]
    public void TC_005_GUIActivatesObstructionAlarm()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.ActivateObstructionAlarm();

        // Assert
        Assert.True(gui.IsObstructionAlarmActive());
    }

    [Fact]
    public void TC_006_ObstructionAlarmInactivatedWhenObstructionNotDetected()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.DeactivateObstructionAlarm();

        // Assert
        Assert.False(gui.IsObstructionAlarmActive());
    }

    [Fact]
    public void TC_007_ObstructionAlarmHasHighPriority()
    {
        // Arrange
        var alarm = new Alarm();

        // Act
        alarm.SetPriority(AlarmPriority.High);

        // Assert
        Assert.Equal(AlarmPriority.High, alarm.Priority);
    }

    [Fact]
    public void TC_008_GUIComputesLeakageAmountBasedOnSensorReadings()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.ComputeLeakageAmount(100);

        // Assert
        Assert.Equal(100, gui.LeakageAmount);
    }
}
